 const [error,setError]=useState(""),[connectionError,setConnectionError]=useState(""),[notice,setNotice]=useState("");
 const [panel,setPanel]=useState<Panel|null>(null),[form,setForm]=useState<Form|null>(null),[editing,setEditing]=useState(false),[busy,setBusy]=useState(false),[search,setSearch]=useState("");
 const [observation,setObservation]=useState<Observation|null>(null),[logError,setLogError]=useState(""),[log,setLog]=useState(tr("Caricamento dei dettagli…", "Loading details…")),[transfer,setTransfer]=useState<Transfer|null>(null),[filter,setFilter]=useState("all"),[environmentQuery,setEnvironmentQuery]=useState("");
 const [transferError,setTransferError]=useState("");
 const origin=useRef<HTMLElement|null>(null);
 const base=`${getBackendBaseURL()}/api/harness/environments`;
 async function load(signal?:AbortSignal){
  try{
  const replies=await Promise.allSettled([fetch(base,{signal}),fetch(`${getBackendBaseURL()}/api/harness/tool-versions`,{signal})]);
  if(signal?.aborted)return;
  const env=replies[0];
  if(env.status==="fulfilled"&&env.value.ok){setData(await env.value.json());setConnectionError("");}
  else setConnectionError(env.status==="fulfilled"&&env.value.status===403?tr("Non hai il permesso di gestire gli ambienti.", "You do not have permission to manage environments."):tr("Aggiornamenti non disponibili: lo stato mostrato potrebbe non essere attuale.", "Updates unavailable: the status shown may be out of date."));
  const lib=replies[1];if(lib.status==="fulfilled"&&lib.value.ok){const v=await lib.value.json();if(Array.isArray(v.tools)&&Array.isArray(v.versions))setVersions(v);}
  }catch{if(!signal?.aborted)setConnectionError(tr("Aggiornamenti non disponibili: riprovo automaticamente senza perdere le modifiche aperte.", "Updates unavailable: retrying automatically without losing open changes."));}
 }
 useEffect(()=>{const c=new AbortController();void load(c.signal);const timer=setInterval(()=>void load(c.signal),5000);return()=>{c.abort();clearInterval(timer);};},[base]);
 useEffect(()=>{const id=sessionStorage.getItem("skill-environment-transfer");if(!id)return;const c=new AbortController();void fetch(`${base}/transfers/${id}/status`,{signal:c.signal}).then(async r=>{if(r.ok)setTransfer(await r.json());else if(r.status===404)sessionStorage.removeItem("skill-environment-transfer");}).catch(()=>{});return()=>c.abort();},[base]);
 useEffect(()=>{if(!transfer)return;const server=data?.transfers?.find(t=>t.id===transfer.id);if(server&&newerTransfer(server,transfer)){setTransfer(server);setTransferError("");}},[data?.transfers,transfer?.id,transfer?.updated_at,transfer?.observed_at]);
 useEffect(()=>{if(!transfer||["ready","failed"].includes(transfer.state))return;const c=new AbortController();let timer:ReturnType<typeof setTimeout>|undefined;const id=transfer.id;async function tick(){try{const r=await fetch(`${base}/transfers/${id}/status`,{signal:c.signal,cache:"no-store"});if(!r.ok)throw Error(tr("Stato non disponibile", "Status unavailable"));const value:Transfer=await r.json();if(c.signal.aborted)return;setTransfer(value);setTransferError("");if(value.state==="ready"){setNotice(value.message);void load(c.signal);}}catch{if(!c.signal.aborted)setTransferError(tr("Aggiornamento del trasferimento non disponibile. Riprovo automaticamente; lo stato mostrato potrebbe non essere attuale.", "Transfer update unavailable. Retrying automatically; the status shown may be out of date."));}if(!c.signal.aborted)timer=setTimeout(()=>void tick(),2000);}void tick();return()=>{c.abort();clearTimeout(timer);};},[base,transfer?.id,transfer?.state]);
 function selectTransfer(value:Transfer){setTransfer(value);setTransferError("");sessionStorage.setItem("skill-environment-transfer",value.id);}

 async function readLog(name:string,signal?:AbortSignal){
  try{const r=await fetch(`${base}/${encodeURIComponent(name)}/log`,{signal,cache:"no-store"});const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Dettagli non disponibili", "Details unavailable"));if(signal?.aborted)return;setLog(v.text?.trim()||tr("Non è ancora iniziata una preparazione per questo ambiente.", "No preparation has started for this environment yet."));setObservation(v.observation??null);setLogError("");}
  catch(e){if(!signal?.aborted)setLogError(tr("Aggiornamento dei dettagli non riuscito: lo stato mostrato potrebbe non essere attuale. Riprovo automaticamente.", "Refreshing details failed: the status shown may be out of date. Retrying automatically."));}
 }
 useEffect(()=>{if(panel?.kind!=="log"||!panel.profile)return;const c=new AbortController();let timer:ReturnType<typeof setTimeout>|undefined;const name=panel.profile.name;async function tick(){await readLog(name,c.signal);if(!c.signal.aborted)timer=setTimeout(()=>void tick(),3000);}setLog(tr("Caricamento dei dettagli…", "Loading details…"));setObservation(null);setLogError("");void tick();return()=>{c.abort();clearTimeout(timer);};},[base,panel?.kind,panel?.profile?.name]);
 function open(value:Panel){if(!panel)origin.current=document.activeElement as HTMLElement;setError("");setPanel(value);}
 async function resourceSettings(){setResources(null);open({kind:"resources"});try{const r=await fetch(`${base}/resources/settings`);const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Budget non disponibile", "Budget unavailable"));setResources(v);setOperationLimit(v.settings.max_workers??2);}catch(e){setError(e instanceof Error?e.message:tr("Budget non disponibile", "Budget unavailable"));}}
 async function applyActiveBudget(){setBusy(true);setError("");try{const r=await fetch(`${base}/resources/rebalance`,{method:"POST"});const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Riassegnazione non riuscita", "Reassignment failed"));await load();if(v.pending){setError(v.message);return;}close();setNotice(v.message);}catch(e){setError(e instanceof Error?e.message:tr("Riassegnazione non riuscita", "Reassignment failed"));}finally{setBusy(false);}}
 async function saveResources(){if(!resources)return;setBusy(true);setError("");try{const r=await fetch(`${base}/resources/settings`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({...resources.settings,max_workers:operationLimit})});const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Budget non salvato", "Budget not saved"));close();setNotice(tr("Limite aggiornato senza riavvio. Le nuove ammissioni rispettano il limite. La CPU è condivisa tra le operazioni attive; la RAM in uso non viene ridotta.", "Limit updated without restart. New admissions respect the limit. CPU is shared among active operations; RAM in use is not reduced."));await load();}catch(e){setError(e instanceof Error?e.message:tr("Budget non salvato", "Budget not saved"));}finally{setBusy(false);}}
 function edit(p:Profile,clone=false){setEditing(!clone);setForm({name:p.name+(clone?"-copia":""),display_name:p.display_name+(clone?tr(" — copia", " — copy"):""),purpose:p.purpose,instructions:p.instructions??"",skills:[...p.skills],mode:clone?"on_demand":p.deployment.mode,ephemeral:clone?false:p.deployment.ephemeral,preload_tools:clone?null:p.deployment.preload_tools??null,tool_versions:{...p.deployment.tool_versions}});setSearch("");open({kind:"config",profile:p});}
 function preset(p:Preset){setEditing(false);setForm({...blank(),name:p.id,display_name:p.name,purpose:p.purpose,skills:p.skills});setSearch("");open({kind:"config"});}
 function close(){setPanel(null);setError("");requestAnimationFrame(()=>{if(origin.current?.isConnected)origin.current.focus();});}
 const chosen=new Set(form?.skills??[]);
 const skillUsable=(s:Skill)=>s.enabled&&!s.error&&s.tools.every(t=>data?.skills.some(dependency=>dependency.name===`skill-${t}`&&dependency.enabled));
 const selectedTools=[...new Set((data?.skills??[]).filter(s=>chosen.has(s.name)&&skillUsable(s)).flatMap(s=>s.tools))];
 const versionTools=[...new Set([...selectedTools,...(versions?.tools.filter(t=>selectedTools.includes(t.id)).flatMap(t=>t.dependencies??[])??[])])];
 async function save(){if(!form)return;setBusy(true);setError("");try{
  const r=await fetch(editing?`${base}/${encodeURIComponent(form.name)}`:base,{method:editing?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,tool_versions:Object.fromEntries(Object.entries(form.tool_versions).filter(([t])=>versionTools.includes(t))),preload_tools:form.preload_tools?.filter(t=>selectedTools.includes(t))??null})});const v=await r.json();if(!r.ok)throw Error(typeof v.detail==="string"?v.detail:tr("Controlla nome, scopo e skill selezionate", "Check name, purpose and selected skills"));close();setForm(null);setNotice(tr("Ambiente salvato. Il precaricamento, se scelto, continua sul server.", "Environment saved. Preloading, if chosen, continues on the server."));await load();
 }catch(e){setError(e instanceof Error?e.message:tr("Salvataggio non riuscito", "Save failed"));}finally{setBusy(false);}}
 async function action(p:Profile,kind:"prepare"|"cache"|"log"|"cancel"){
  setError("");if(kind==="log"){if(panel?.kind==="log"&&panel.profile?.name===p.name)await readLog(p.name);else open({kind:"log",profile:p});return;}setBusy(true);
  try{const r=await fetch(`${base}/${encodeURIComponent(p.name)}/${kind}`,{method:kind==="prepare"||kind==="cancel"?"POST":kind==="cache"?"DELETE":"GET"});const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Operazione non riuscita", "Operation failed"));
   {setNotice(kind==="prepare"?tr(`${p.display_name}: preparazione avviata. Puoi lasciare la pagina.`, `${p.display_name}: preparation started. You can leave the page.`):kind==="cancel"?tr("Annullamento richiesto. Le verifiche condivise con altri ambienti possono continuare.", "Cancellation requested. Checks shared with other environments may continue."):tr("Cache liberata. Progetti e lezioni sono conservati.", "Cache cleared. Projects and lessons are kept."));await load();}
  }catch(e){setError(e instanceof Error?e.message:tr("Operazione non riuscita", "Operation failed"));}finally{setBusy(false);}
 }
 async function prepareAll(){setBusy(true);setError("");try{const r=await fetch(base+"/prepare-preloaded",{method:"POST"});const v=await r.json();if(!r.ok)throw Error(v.detail||tr("Preparazione non avviata", "Preparation not started"));setNotice(tr(`${v.environments.length} ${v.environments.length===1?tr("ambiente precaricato in preparazione", "preloaded environment being prepared"):tr("ambienti precaricati in preparazione", "preloaded environments being prepared")}. Le richieste già in corso non vengono duplicate.`, `${v.environments.length} ${v.environments.length===1?tr("ambiente precaricato in preparazione", "preloaded environment being prepared"):tr("ambienti precaricati in preparazione", "preloaded environments being prepared")}. Requests already in progress are not duplicated.`));await load();}catch(e){setError(e instanceof Error?e.message:tr("Preparazione non avviata", "Preparation not started"));}finally{setBusy(false);}}
 function terminal(p:Profile){const url=`/terminal?environment=${encodeURIComponent(p.name)}`;const popup=window.open(url,`skill-terminal-${p.name}`,"popup,width=1200,height=800");if(popup){popup.opener=null;popup.focus();}else window.location.assign(url);}
